    String armClass = Naming.genericFunctionPkgClass(owner, fname,
            NamingCzar.genericDecoration(templateStaticParams(), null, ifNone), arrow);
    mv.visitMethodInsn(Opcodes.INVOKESTATIC, armClass, Naming.APPLIED_METHOD, sig);
}
